"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[28038],{28038:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-demand-for-depth.png\\"\\n          title=\\"The Depth\\"\\n          author=\\"Patrick S\xfcskind\\"\\n          publisher=\\"Open Books\\"\\n          publishedDate=\\"2014-07-20\\"\\n          isbn=\\"9788932902777\\"\\n          rating=5\\n          tags=\\"novel\\"\\n        />\\n</center>\\n\\n## Review\\nA short story with no fluff. It\'s short but intense, impactful, and has deep resonance.  \\n<br>\\nIn the book, it\'s expressed as an artist and a critic, but this duality exists everywhere.  \\nIt shows the reality where <mark>depth</mark> becomes a yardstick for measuring the depth of life, and ```social conditions``` gradually eat away at even individual lives.  \\n<br>\\nThis yardstick is also applied to oneself.  \\nIt seems that the yardstick one applies can turn into development or into despair.\\n"}')}}]);